        if (n <= 0 || paths == null) {
            return "cannot be travelled";
        }
        // Determine whether paths represent 2D coordinates (length 4) or linear node IDs (length 2)
        boolean is2D = paths.length > 0 && paths[0].length == 4;
        if (is2D) {
            // Build adjacency for 2D grid
            Map<String, List<String>> graph = new HashMap<>();
            for (int[] p : paths) {
                if (p.length != 4) continue;
                String a = p[0] + "#" + p[1];
                String b = p[2] + "#" + p[3];
                graph.computeIfAbsent(a, k -> new ArrayList<>()).add(b);
                graph.computeIfAbsent(b, k -> new ArrayList<>()).add(a);
            }
            String startKey = (start.length >= 2 ? start[0] + "#" + start[1] : "0#0");
            String endKey = (end.length >= 2 ? end[0] + "#" + end[1] : "0#0");
            Set<String> visited = new HashSet<>();
            Deque<String> queue = new ArrayDeque<>();
            queue.offer(startKey);
            visited.add(startKey);
            while (!queue.isEmpty()) {
                String cur = queue.poll();
                if (cur.equals(endKey)) {
                    return "can be travelled";
                }
                for (String nb : graph.getOrDefault(cur, Collections.emptyList())) {
                    if (!visited.contains(nb)) {
                        visited.add(nb);
                        queue.offer(nb);
                    }
                }
            }
            return "cannot be travelled";
        } else {
            // Treat nodes as integer IDs
            Map<Integer, List<Integer>> graph = new HashMap<>();
            for (int[] p : paths) {
                if (p.length != 2) continue;
                int a = p[0], b = p[1];
                graph.computeIfAbsent(a, k -> new ArrayList<>()).add(b);
                graph.computeIfAbsent(b, k -> new ArrayList<>()).add(a);
            }
            int startNode = start.length > 0 ? start[0] : 0;
            int endNode = end.length > 0 ? end[0] : 0;
