public String sortString(String s) {
    if (s == null || s.isEmpty()) return "";
    TreeMap<Character, Integer> freq = new TreeMap<>();
    for (char c : s.toCharArray()) {
        freq.merge(c, 1, Integer::sum);
    }
    StringBuilder result = new StringBuilder();
    while (!freq.isEmpty()) {
        // ascending phase
        Character key = freq.firstKey();
        result.append(key);
        decrementKey(freq,key);
        char last = key;
        while (true) {
            Character next = freq.higherKey(last);
            if (next == null) break;
            result.append(next);
            decrementKey(freq,next);
            last = next;
        }
        // descending phase
        if (freq.isEmpty()) break; // nothing left
        Character lastKey = freq.lastKey();
        result.append(lastKey);
        decrementKey(freq,lastKey);
        last = lastKey;
        while (true) {
            Character prev = freq.lowerKey(last);
            if (prev == null) break;
            result.append(prev);
            decrementKey(freq, prev);
            last = prev;
        }
    }
    return result.toString();
}

private void decrementKey(TreeMap<Character,Integer> map, Character key) {
    int cnt = map.get(key);
    if (cnt == 1) map.remove(key);
    else map.put(key, cnt-1);
}

